use kassiber_pydecimal::Decimal;
fn old_fixed_equal(decimal: &Decimal, raw: &[u8]) -> bool {
    fn compare(decimal: &Decimal, raw: &[u8]) -> Option<bool> {
        let d = decimal;
        let raw = if d.is_sign_negative() {
            raw.strip_prefix(b"-")?
        } else {
            raw
        };
        if d.is_zero() && d.exponent() >= 0 {
            return Some(raw == b"0");
        }
        let digits =
            usize::try_from(i128::from(d.adjusted()) - i128::from(d.exponent()) + 1).ok()?;
        let int_len = i128::from(d.adjusted()) + 1;
        let (left, right) = if d.exponent() >= 0 {
            let padding = usize::try_from(d.exponent()).ok()?;
            if raw.len() != digits.checked_add(padding)?
                || !raw[digits..].iter().all(|&b| b == b'0')
            {
                return Some(false);
            }
            (&raw[..digits], &b""[..])
        } else if int_len > 0 {
            let int_len = usize::try_from(int_len).ok()?;
            if raw.len() != digits.checked_add(1)? || raw.get(int_len) != Some(&b'.') {
                return Some(false);
            }
            (&raw[..int_len], &raw[int_len + 1..])
        } else {
            let padding = usize::try_from(-int_len).ok()?;
            let rest = raw.strip_prefix(b"0.")?;
            if rest.len() != padding.checked_add(digits)?
                || !rest[..padding].iter().all(|&b| b == b'0')
            {
                return Some(false);
            }
            (&rest[padding..], &b""[..])
        };
        Some(d.coefficient_matches_ascii(left, right))
    }
    compare(decimal, raw).unwrap_or(false)
}

fn new_fixed_equal(decimal: &Decimal, raw: &[u8]) -> bool {
    fn compare(d: &Decimal, raw: &[u8]) -> Option<bool> {
        let raw = if d.is_sign_negative() { raw.strip_prefix(b"-")? } else { raw };
        if d.is_zero() && d.exponent() >= 0 { return Some(raw == b"0"); }
        let (left, right) = if d.exponent() >= 0 {
            let padding = usize::try_from(d.exponent()).ok()?;
            let end = raw.len().checked_sub(padding)?;
            let coefficient = &raw[..end];
            if coefficient.first().is_none_or(|&b| b == b'0') || !raw[end..].iter().all(|&b| b == b'0') { return Some(false); }
            (coefficient, &b""[..])
        } else {
            let scale = usize::try_from(-i128::from(d.exponent())).ok()?;
            let point = raw.len().checked_sub(scale.checked_add(1)?)?;
            if raw.get(point) != Some(&b'.') || point == 0 { return Some(false); }
            let left = &raw[..point];
            let right = &raw[point+1..];
            if left == b"0" {
                let start = right.iter().position(|&b| b != b'0').unwrap_or(right.len()-1);
                (&right[start..], &b""[..])
            } else {
                if left[0] == b'0' { return Some(false); }
                (left, right)
            }
        };
        Some(d.coefficient_matches_ascii(left,right))
    }
    compare(decimal,raw).unwrap_or(false)
}

fn main() {
 let args: Vec<_> = std::env::args().collect();
 let width: usize = args[2].parse().unwrap();
 let exponent: i64 = args[3].parse().unwrap();
 let text: String = "1234567890".repeat(width.div_ceil(10)).chars().take(width).collect();
 let d: Decimal = format!("{text}E{exponent}").parse().unwrap();
 let raw = d.to_fixed_string().unwrap();
 for _ in 0..(20_000_000/width) {
  let d=std::hint::black_box(&d); let raw=std::hint::black_box(raw.as_bytes());
  let equal=if args[1]=="old" {old_fixed_equal(d,raw)} else {new_fixed_equal(d,raw)};
  assert!(std::hint::black_box(equal));
 }
}
